{
  "measurement_needs": [
    "Glass transition temperature (Tg) of an amorphous solid dispersion",
    "Thermal degradation onset and residual moisture/solvent content prior to heating"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ18",
      "role": "primary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC directly measures the glass transition temperature (Tg) by detecting the step change in heat capacity as the amorphous dispersion transitions from a rigid glass to a rubbery state. Note that the tested sample aliquot is thermally altered during the run, and absorbed moisture can significantly lower the measured Tg.",
      "accessories_to_confirm": [
        "Sub-ambient cooling system (if Tg is near or below room temperature)",
        "Modulated DSC (MDSC) capability (to separate reversible Tg from overlapping non-reversible events like enthalpy relaxation or solvent evaporation)",
        "Appropriate sample pans and press (e.g., hermetic or pinhole pans)"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA measures mass loss as a function of temperature to determine the thermal degradation onset (setting a safe upper temperature limit for the DSC) and to quantify residual solvent or moisture, which acts as a plasticizer and depresses Tg.",
      "accessories_to_confirm": [
        "Compatible sample pans (e.g., platinum or aluminum)",
        "Inert purge gas supply (nitrogen)"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Powder X-ray Diffraction (PXRD)",
      "why_useful": "PXRD is standard for confirming that the solid dispersion is fully amorphous initially and for directly detecting drug recrystallization during stability studies."
    },
    {
      "technique": "Dynamic Vapor Sorption (DVS)",
      "why_useful": "DVS measures moisture uptake as a function of relative humidity, helping predict how ambient humidity will plasticize the dispersion and lower its Tg during storage."
    }
  ],
  "clarifying_question": null,
  "summary": "You can measure the glass transition temperature (Tg) of your amorphous solid dispersion using the Differential Scanning Calorimeter (EQ18), which detects the heat capacity step at the glassy-to-rubbery transition. It is good practice to first run Thermogravimetric Analysis (EQ17) to establish a safe upper heating limit and quantify residual moisture or solvent that could plasticize the sample and shift the Tg. Please note that these thermal measurements are destructive to the small sample portion analyzed."
}

