{
  "measurement_needs": [
    "Mass fraction of water and volatile components lost upon heating",
    "Differentiation between bound water (hydrates) and surface moisture or other volatiles"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ17",
      "role": "primary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA directly measures the weight loss of your drug powder as it is heated, allowing you to quantify the total percentage of water and other volatiles present. Note that this method is destructive and measures total mass loss, so it cannot chemically distinguish water from residual organic solvents if they evaporate in the same temperature range.",
      "accessories_to_confirm": [
        "Compatible sample pans (e.g., platinum or aluminum pans)",
        "Inert purge gas supply (e.g., nitrogen)"
      ]
    },
    {
      "instrument_id": "EQ18",
      "role": "supplementary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC measures heat flow associated with thermal transitions, such as broad endothermic peaks from water evaporation or sharper dehydration events, helping you distinguish surface moisture from crystal hydrate water alongside TGA mass-loss data.",
      "accessories_to_confirm": [
        "Pinhole or non-hermetic sample pans and lids (to allow volatiles to escape)",
        "Sample crimper/press",
        "Inert purge gas supply"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "Karl Fischer Titration",
      "why_useful": "Specifically and selectively quantifies water content without interference from other volatile solvents or thermal decomposition."
    },
    {
      "technique": "Evolved Gas Analysis (TGA-FTIR or TGA-MS)",
      "why_useful": "Identifies the chemical identity of the gases evolving during TGA heating to separate water loss from other volatile solvents."
    },
    {
      "technique": "Dynamic Vapor Sorption (DVS)",
      "why_useful": "Measures equilibrium moisture uptake and desorption isotherms across controlled relative humidity levels to characterize hygroscopicity during storage."
    }
  ],
  "clarifying_question": null,
  "summary": "You can quantify the total water and volatile content of your drug powder using the Thermogravimetric Analyzer (EQ17), which measures mass loss as the sample is heated. Because TGA is destructive and measures total weight loss rather than chemical identity, pairing it with Differential Scanning Calorimetry (EQ18) can help differentiate surface moisture from bound hydrate water. If you need to selectively measure water separately from other organic volatiles, Karl Fischer titration would be required but is not on the equipment list."
}

{
  "measurement_needs": [
    "Direct nanoscale imaging of individual gold nanoparticles to determine particle morphology (spheres vs. rods) and physical dimensions"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ11",
      "role": "primary",
      "technique": "Transmission Electron Microscopy (TEM)",
      "why": "TEM provides sub-nanometer resolution capable of directly imaging individual gold nanoparticles of any size, allowing you to clearly distinguish spheres from nanorods and measure the exact length and diameter of each particle. Note that samples must be dried onto a grid and imaged under high vacuum, which can sometimes induce drying-related aggregation.",
      "accessories_to_confirm": [
        "Standard sample holder and carbon-coated TEM grids (consumables)",
        "Calibrated digital camera or STEM detector for image capture"
      ]
    },
    {
      "instrument_id": "EQ10",
      "role": "primary",
      "technique": "Field-Emission Scanning Electron Microscopy (FE-SEM)",
      "why": "Because this instrument has a field-emission source, it can directly resolve the shape and dimensions of larger gold nanoparticles and nanorods (typically above 15–20 nm) deposited on a conductive substrate. However, if your nanoparticles are smaller than ~10–15 nm, TEM (EQ11) will provide much sharper boundaries and more accurate sizing.",
      "accessories_to_confirm": [
        "High-resolution secondary electron (SE) or backscattered electron (BSE) detector",
        "Conductive substrates such as silicon wafers or SEM stubs"
      ]
    },
    {
      "instrument_id": "EQ20",
      "role": "supplementary",
      "technique": "Dynamic Light Scattering (DLS) and Zeta Potential",
      "why": "While DLS cannot produce images or directly distinguish rods from spheres on its own, it is a fast way to check the bulk hydrodynamic size distribution, aggregation state, and surface charge (zeta potential) of your gold nanoparticles directly in liquid suspension. Note that DLS assumes spherical particles, so rod-shaped particles will yield an apparent equivalent sphere diameter rather than true length and width.",
      "accessories_to_confirm": [
        "Sizing cuvettes and folded capillary zeta potential cells"
      ]
    }
  ],
  "not_available": [
    {
      "technique": "UV-Vis-NIR Spectrophotometry",
      "why_useful": "Gold nanospheres exhibit a single surface plasmon resonance absorption peak (~520 nm), whereas gold nanorods exhibit two distinct peaks (transverse and longitudinal), providing a rapid bulk screen of particle shape and aspect ratio in solution."
    },
    {
      "technique": "Atomic Force Microscopy (AFM)",
      "why_useful": "Provides direct 3D topographic height measurements of individual nanoparticles deposited on an atomically flat substrate without requiring high vacuum."
    }
  ],
  "clarifying_question": null,
  "summary": "To directly visualize your gold nanoparticles and measure their individual shapes and dimensions, the Philips CM12 TEM (EQ11) is the best choice as it easily resolves both small and large spheres and rods. For particles larger than about 15–20 nm, the field-emission SEM (EQ10) can also image particle morphology, while the Zetasizer Pro (EQ20) is useful as a supplementary tool to assess colloidal stability and aggregation in suspension."
}

